'use strict';
// v18: paid reserve, temporary fusion and individual skill triggers.
PA.fusion='assets/fusion-spring-spring-v1.ogg';
let fusionShown=0;
function selectedUid(){return !selected?null:selected.kind==='hand'?selected.uid:(selected.kind==='bench'?S.bench:S.board)[selected.pos];}
function selectedCard(){return G.card(S,selectedUid());}
function skillTriggerText(t){const g=t.trigger,n=g.limit;switch(g.kind){case'attacks':return (g.startFull?L('Starts fully charged · then ','Começa com carga cheia · depois '):'')+n+' '+L('basic attacks','ataques básicos');case'received':if(['elf_guardian','gladiator','blackfang_guardian'].includes(t.id))return n+' '+L('basic attacks received','ataques básicos recebidos');return n+' '+L('hits received (attacks or skills)','golpes recebidos (ataques ou skills)');case'time':return L('Every ','A cada ')+n+' s';case'damage':return L('Deal damage equal to ','Causar dano equivalente a ')+(n*100)+'% '+L('of starting attack','do ataque inicial');case'block':return L('Blocks every fourth basic attack received','Bloqueia cada quarto ataque básico recebido');case'health':return L('Passive · while at 50% health or less','Passiva · enquanto estiver com 50% de vida ou menos');default:return L('Passive','Passiva');}}
function skillDescription(t){if(t.id==='cavalier')return L('Starts each round ready to charge the nearest enemy. On contact, strike for 180% attack and stun for 1 second. Recharge with 6 basic attacks. Control interrupts an ongoing charge.','Começa cada rodada pronto para investir contra o inimigo mais próximo. No contato, causa 180% do ataque e atordoa por 1 segundo. Recarrega com 6 ataques básicos. Controle interrompe uma investida em andamento.');return I18n.t(t.detail).replace(/^(?:After \d+ basic attacks, |Após \d+ ataques básicos, )/i,'');}
function rosterSlot(c,kind,i){const chosen=selected?.kind===kind&&selected.pos===i;return '<button class="'+(kind==='field'?'field-slot ':'bench-slot ')+(c?'has-art ':'empty ')+(chosen?'selected ':'')+(c?.fused?'fused-unit ':'')+(selected?.kind==='hand'&&!c?'target ':'')+'" '+(kind==='field'?'style="left:'+GamePosition(i).x+'%;top:'+GamePosition(i).y+'%" ':'')+'data-act="'+(kind==='field'?'slot':'bench-slot')+'" data-pos="'+i+'" data-unit="'+(c?.uid||'')+'" aria-label="'+(c?G.BY[c.type].name+(c.fused?' · '+L('Fused','Fundido'):''):L('Empty position ','Posição vazia ')+(i+1))+'">'+(c?P.sprite(c.type)+'<small class="lvl">'+(c.fused?'◆':'↑'.repeat(c.level))+'</small>':'<span class="slot-number">'+(i+1)+'</span>')+'</button>';}
function prep(){G.ensureRoster(S);if(selected&&!selectedCard())selected=null;const field='<div class="arena-stage"><div class="field"><canvas id="field" width="430" height="540"></canvas><canvas id="range-overlay" width="430" height="540" aria-hidden="true"></canvas><div class="hidden-enemy"><span class="mask">◇</span><b>Além da névoa</b><p>Adversário revelado no combate</p></div><div class="deployment-backdrop" aria-hidden="true"></div>'+S.board.map((id,i)=>rosterSlot(id?G.card(S,id):null,'field',i)).join('')+'</div></div>';
show('<section class="arena-shell preparation">'+arenaStatus()+field+traitRibbon()+selectionView()+'<div class="bench-dock"><div class="bench-label" aria-label="'+L('Reserve','Banco')+'">'+Icon('units')+' <b>'+S.bench.filter(Boolean).length+'/6</b></div><div class="bench-slots">'+S.bench.map((id,i)=>rosterSlot(id?G.card(S,id):null,'bench',i)).join('')+'</div></div><div class="hand-dock"><div class="hand-tools"><span>Preparação</span><span>'+freezeHandButton()+'<button class="refresh-hand" data-act="refresh-hand" '+(S.energy<1||!S.hand.length?'disabled':'')+' aria-label="'+L('Refresh hand · 1 energy','Reciclar mão · 1 energia')+'">↻ '+Icon('bolt')+'1</button>'+miniAction('piles','cycle',L('Draw ','Compra ')+S.draw.length+' · '+L('discard ','descarte ')+S.discard.length)+'<button class="setup-view-deck" data-act="deck">'+Icon('deck')+'<span>'+L('View deck','Ver deck')+'</span></button>'+'</span></div><div class="hand">'+(S.hand.length?S.hand.map(id=>cardFace(G.card(S,id))).join(''):'<span class="hint">Mão vazia · reposicione ou comece</span>')+'</div></div><div class="arena-actions"><span class="compact-hint">'+L(selected?'Tap field or reserve':'3 paid copies = fusion',selected?'Toque no campo ou banco':'3 cópias pagas = fusão')+'</span><button class="primary" data-act="fight" '+(!G.canFight(S)?'disabled':'')+'>Combater '+Icon('swords')+'</button></div></section>');paintBase($('field').getContext('2d'));paintRange($('range-overlay').getContext('2d'));
}
function selectionView(){if(!selected)return '<div class="selection compact-selection"><span class="hint">'+L('Select a card or move a unit between field and reserve.','Selecione uma carta ou mova entre campo e banco.')+'</span></div>';const c=selectedCard(),t=G.BY[c.type];if(!c)return '';return '<div class="selection compact-selection"><span><b>'+t.name+(c.fused?' ◆':'')+'</b><small>'+(selected.kind==='hand'?Icon('bolt')+G.cost(c)+' · '+(G.canFuse(S,c.uid)?L('Completes fusion','Completa a fusão'):L('Pay to deploy','Pague para posicionar')):skillTriggerText(t))+'</small></span><div>'+miniAction('info','info',L('Details','Detalhes'),'data-id="'+c.uid+'"')+(selected.kind!=='hand'&&G.returnPlan(S,c.uid)?'<button class="mini" data-act="return-hand">'+L('Return to hand','Voltar à mão')+' · ⚡'+G.returnPlan(S,c.uid).paid+'</button>':'')+(selected.kind!=='hand'?miniAction('remove','trash',L('Remove · refund ','Retirar · devolve ')+G.refund(S,c.uid)):'' )+'</div></div>';}
function fieldClick(pos){rosterClick('field',pos);}
function rosterClick(kind,pos){if(S?.phase!=='prep')return;const slots=kind==='bench'?S.bench:S.board;if(!selected){if(slots[pos])selected={kind,pos};else toast(L('Select a card first.','Selecione uma carta primeiro.'));prep();return;}
const before=rosterRects(),serial=S.fusionSerial||0;let ok=false;if(selected.kind==='hand'){ok=G.deploy(S,selected.uid,pos,kind);}else if(selected.kind===kind&&selected.pos===pos){selected=null;prep();return;}else ok=G.transfer(S,selected.kind,selected.pos,kind,pos);
if(ok){selected=null;prep();save();if((S.fusionSerial||0)>serial)playFusion(before);else sound(580);}else toast(L('Check energy, available space and the round unit limit.','Confira energia, espaço disponível e limite de unidades da rodada.'));
}
function rosterRects(){const out={};for(const el of document.querySelectorAll('[data-unit],[data-act="hand"]')){const id=el.dataset.unit||el.dataset.id;if(id)out[id]=el.getBoundingClientRect();}return out;}
function playFusion(before){const f=S.lastFusion;if(!f)return;fusionShown=f.serial;const destination=document.querySelector('[data-unit="'+f.uid+'"]');if(!destination)return;AudioSystem.play('fusion',.8,false);destination.classList.add('fusion-flash');setTimeout(()=>destination.classList.remove('fusion-flash'),750);if(REDUCED_MOTION)return;const end=destination.getBoundingClientRect();for(const {uid} of f.origins){const start=before[uid];if(!start||uid===f.uid)continue;for(let n=0;n<5;n++){const dot=document.createElement('i');dot.className='fusion-particle';dot.style.left=start.x+start.width/2+'px';dot.style.top=start.y+start.height/2+'px';document.body.append(dot);const a=dot.animate([{transform:'translate(0,0)',opacity:0},{opacity:1,offset:.15},{transform:'translate('+(end.x+end.width/2-start.x-start.width/2)+'px,'+(end.y+end.height/2-start.y-start.height/2)+'px)',opacity:0}],{duration:450+n*35,delay:n*20,easing:'ease-in'});a.onfinish=()=>dot.remove();}}}
window.addEventListener('click',e=>{const el=e.target.closest('[data-act="bench-slot"]');if(!el||el.disabled)return;e.stopImmediatePropagation();AudioSystem.unlock();rosterClick('bench',+el.dataset.pos);},true);

// Pointer gestures work on mouse, touch and pen. Stationary holds retain inspection.
function rosterAim(held,e){const touch=(held.pointerType||e.pointerType)==='touch';if(!touch)return{x:e.clientX,y:e.clientY,touch};const r=held.originRect||held.el?.getBoundingClientRect?.()||{left:held.x,top:held.y,width:0};const x=r.left+(e.clientX-held.x)+r.width/2,y=r.top+(e.clientY-held.y)-18;return{x:Math.max(8,Math.min(typeof window!=='undefined'?window.innerWidth-8:Infinity,x)),y:Math.max(8,Math.min(typeof window!=='undefined'?window.innerHeight-8:Infinity,y)),touch};}
function dragTraitPreview(held,active){if(typeof traitRibbon!=='function')return;if(active){held.selectionBefore=selected;selected=held.kind==='hand'?{kind:'hand',uid:held.uid}:{kind:held.kind,pos:held.pos};}else selected=held.selectionBefore||null;const ribbon=document.querySelector('.preparation .trait-ribbon');if(ribbon)ribbon.outerHTML=traitRibbon();const info=document.querySelector('.preparation .selection');if(info)info.outerHTML=selectionView();I18n.apply(document.querySelector('.preparation'));}
function dragTarget(x,y){return document.elementFromPoint(x,y)?.closest('[data-act="slot"],[data-act="bench-slot"],.hand-dock');}
function canDropRoster(source,target){if(typeof window!=='undefined'&&window.JourneyTutorial&&!window.JourneyTutorial.allowDrop(target))return false;if(S?.phase!=='prep'||!target)return false;if(target.classList.contains('hand-dock'))return source.kind!=='hand'&&!!G.returnPlan(S,(source.kind==='bench'?S.bench:S.board)[source.pos]);const kind=target.dataset.act==='bench-slot'?'bench':'field',pos=+target.dataset.pos,slots=kind==='bench'?S.bench:S.board;if(!Number.isInteger(pos)||pos<0||pos>=slots.length)return false;if(source.kind==='hand'){const c=G.card(S,source.uid);return !!c&&S.hand.includes(source.uid)&&S.energy>=G.cost(c)&&(G.canFuse(S,source.uid)||!slots[pos]&&(kind==='bench'||S.board.filter(Boolean).length<G.maxUnits(S)));}const from=source.kind==='bench'?S.bench:S.board;return !!from[source.pos]&&(source.kind===kind||kind==='bench'||!!slots[pos]||S.board.filter(Boolean).length<G.maxUnits(S));}
function startRosterDrag(held,e){AudioSystem.unlock();const rect=held.el.getBoundingClientRect(),ghost=held.el.cloneNode(true);ghost.classList.add('roster-drag-ghost');ghost.classList.remove('selected','target');ghost.setAttribute('aria-hidden','true');ghost.inert=true;ghost.style.cssText='position:fixed!important;left:'+rect.left+'px!important;top:'+rect.top+'px!important;width:'+rect.width+'px!important;height:'+rect.height+'px!important;transition:none!important;animation:none!important;transform:translate(0px,0px);';held.originRect=rect;dragTraitPreview(held,true);document.body.appendChild(ghost);held.ghost=ghost;if((held.pointerType||e.pointerType)==='touch'){held.aim=document.createElement('i');held.aim.className='roster-drop-aim';held.aim.setAttribute('aria-hidden','true');document.body.appendChild(held.aim);}held.el.classList.add('drag-source');try{held.el.setPointerCapture(e.pointerId);}catch{}document.body.classList.add('roster-dragging');updateRosterDrag(held,e);}
function updateRosterDrag(held,e){if(!held.ghost)return;held.ghost.style.transform='translate('+(e.clientX-held.x)+'px,'+(e.clientY-held.y)+'px)';if(held.target)held.target.classList.remove('drop-valid','drop-invalid');const aim=rosterAim(held,e);if(held.aim){held.aim.style.left=aim.x+'px';held.aim.style.top=aim.y+'px';}held.target=dragTarget(aim.x,aim.y);if(held.target)held.target.classList.add(canDropRoster(held,held.target)?'drop-valid':'drop-invalid');}
function finishRosterDrag(held,e){const aim=e?rosterAim(held,e):null,target=e?.type==='pointerup'&&S?.phase==='prep'&&!$('overlay')?dragTarget(aim.x,aim.y):null,valid=canDropRoster(held,target);held.ghost?.remove();held.aim?.remove();held.el.classList.remove('drag-source');held.target?.classList.remove('drop-valid','drop-invalid');document.body.classList.remove('roster-dragging');try{if(held.el.hasPointerCapture(held.pointer))held.el.releasePointerCapture(held.pointer);}catch{}if(!valid){dragTraitPreview(held,false);if(target)toast(L('Check energy, available space and the round unit limit.','Confira energia, espaço disponível e limite de unidades da rodada.'));return;}selected=held.kind==='hand'?{kind:'hand',uid:held.uid}:{kind:held.kind,pos:held.pos};if(target.classList.contains('hand-dock')){returnSelectedToHand();return;}rosterClick(target.dataset.act==='bench-slot'?'bench':'field',+target.dataset.pos);}
document.addEventListener('dragstart',e=>{if(e.target.closest('.preparation .unit-card,.preparation .field-slot,.preparation .bench-slot'))e.preventDefault();});


// A freeze reserves the current remaining hand for the next round only.
function freezeHandButton(){const on=!!S?.handFrozen,label=L(on?'Unfreeze hand':'Freeze hand',on?'Descongelar mão':'Congelar mão');return '<button class="freeze-hand '+(on?'is-frozen':'')+'" data-act="freeze-hand" aria-pressed="'+on+'" aria-label="'+label+'" title="'+label+'" '+(!S?.hand.length&&!on?'disabled':'')+'><span aria-hidden="true">❄</span><span class="freeze-state">'+L(on?'Frozen':'Freeze',on?'Congelada':'Congelar')+'</span></button>';}
window.addEventListener('click',e=>{const button=e.target.closest('[data-act="freeze-hand"]');if(!button||button.disabled||S?.phase!=='prep')return;e.stopImmediatePropagation();AudioSystem.unlock();if(!G.toggleHandFreeze(S))return;save();AudioSystem.play('click',.3);prep();},true);

function returnSelectedToHand(){if(G.returnToHand(S,selectedUid())){selected=null;save();prep();sound(580);}else toast(L('Return requires a free hand slot and a unit played this round, after the last hand refresh.','É preciso espaço na mão e uma unidade jogada nesta rodada, após a última reciclagem.'));}
window.addEventListener('click',e=>{if(!e.target.closest('[data-act="return-hand"]'))return;e.stopImmediatePropagation();returnSelectedToHand();},true);
